const crypto = require('crypto');
const body = $json.body || $json;
const action = String(body.action || '').toLowerCase();
const authorization = String($json.headers?.authorization || $json.headers?.Authorization || '');
const token = authorization.startsWith('Bearer ') ? authorization.slice(7) : '';
const secret = String($env.ADMIN_CONTROL_SECRET || '');
const serviceId = String($env.RENDER_SERVICE_ID || '');
const apiKey = String($env.RENDER_API_KEY || '');

function verifyToken(value) {
  try {
    if (!secret || !value) return false;
    const [encoded, signature] = value.split('.');
    if (!encoded || !signature) return false;
    const expected = crypto.createHmac('sha256', secret).update(encoded).digest('base64url');
    const a = Buffer.from(signature);
    const b = Buffer.from(expected);
    if (a.length !== b.length || !crypto.timingSafeEqual(a, b)) return false;
    const payload = JSON.parse(Buffer.from(encoded, 'base64url').toString('utf8'));
    return payload.role === 'admin' && Number(payload.exp) > Math.floor(Date.now() / 1000);
  } catch { return false; }
}

if (!verifyToken(token)) return [{ json: { success: false, message: 'Unauthorized or expired admin session.' } }];
if (!serviceId || !apiKey) return [{ json: { success: false, message: 'Render control is not configured in n8n.' } }];
if (!['status', 'on', 'off'].includes(action)) return [{ json: { success: false, message: 'Invalid action.' } }];

const base = `https://api.render.com/v1/services/${serviceId}`;
let method = 'GET';
let url = base;
if (action === 'on') { method = 'POST'; url = `${base}/resume`; }
if (action === 'off') { method = 'POST'; url = `${base}/suspend`; }

try {
  const response = await this.helpers.httpRequest({ method, url, headers: { Authorization: `Bearer ${apiKey}`, Accept: 'application/json' }, returnFullResponse: true });
  let data = response.body;
  if (typeof data === 'string' && data.trim()) { try { data = JSON.parse(data); } catch {} }
  let status = 'unknown';
  if (action === 'off') status = 'suspended';
  else if (action === 'on') status = 'resuming';
  else status = data?.suspended === 'suspended' ? 'suspended' : 'running';
  return [{ json: { success: true, action, status, message: action === 'status' ? `Backend is ${status}.` : `Render ${action === 'on' ? 'resume' : 'suspend'} request accepted.`, renderStatusCode: response.statusCode } }];
} catch (error) {
  const statusCode = error.statusCode || error.response?.status || 502;
  return [{ json: { success: false, message: `Render API request failed with HTTP ${statusCode}.`, renderStatusCode: statusCode } }];
}
